public <T extends Command, C extends CommandCallback<T>> void send(final String addr, final T command, final C callback) {
    try {
      getConn(addr).request(command, callback);
    } catch (Exception ex) {
      if (callback != null) {
        callback.onFailed(command, ex);
      } else {
        throw ex;
      }
    }
  }
